class BigNumCalculator:
    TENS = 10
    ZERO_CHAR = '0'
    MINUS_SIGN = '-'

    @staticmethod
    def _pad_to_length(num, length):
        return num.zfill(length)

    @staticmethod
    def _remove_leading_zeros(result_list):
        while len(result_list) > 1 and result_list[0] == BigNumCalculator.ZERO_CHAR:
            result_list.pop(0)
        return result_list

    @staticmethod
    def _determine_sign_and_order(num1, num2):
        if len(num1) < len(num2):
            return num2, num1, True
        elif len(num1) > len(num2):
            return num1, num2, False
        else:
            if num1 < num2:
                return num2, num1, True
            else:
                return num1, num2, False

    @classmethod
    def add(cls, num1, num2):
        max_length = max(len(num1), len(num2))
        num1 = cls._pad_to_length(num1, max_length)
        num2 = cls._pad_to_length(num2, max_length)

        carry = 0
        result = []
        for i in range(max_length - 1, -1, -1):
            digit_sum = int(num1[i]) + int(num2[i]) + carry
            carry = digit_sum // cls.TENS
            digit = digit_sum % cls.TENS
            result.insert(0, str(digit))

        if carry > 0:
            result.insert(0, str(carry))

        return ''.join(result)

    @classmethod
    def subtract(cls, num1, num2):
        num1, num2, negative = cls._determine_sign_and_order(num1, num2)

        max_length = max(len(num1), len(num2))
        num1 = cls._pad_to_length(num1, max_length)
        num2 = cls._pad_to_length(num2, max_length)

        borrow = 0
        result = []
        for i in range(max_length - 1, -1, -1):
            digit_diff = int(num1[i]) - int(num2[i]) - borrow

            if digit_diff < 0:
                digit_diff += cls.TENS
                borrow = 1
            else:
                borrow = 0

            result.insert(0, str(digit_diff))

        cls._remove_leading_zeros(result)

        if negative:
            result.insert(0, cls.MINUS_SIGN)

        return ''.join(result)

    @staticmethod
    def multiply(num1, num2):
        len1, len2 = len(num1), len(num2)
        result = [0] * (len1 + len2)

        for i in range(len1 - 1, -1, -1):
            for j in range(len2 - 1, -1, -1):
                mul = int(num1[i]) * int(num2[j])
                p1, p2 = i + j, i + j + 1
                total = mul + result[p2]

                result[p1] += total // BigNumCalculator.TENS
                result[p2] = total % BigNumCalculator.TENS

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(map(str, result[start:]))
